import * as THREE from 'three';

// Stable-fluids pipeline, matching the main.js mechanism: splat → curl →
// vorticity → advection → divergence → Jacobi pressure → gradient subtraction.
// This is readable project code, not an imported copy of the site's minified bundle.
const vertex = `varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}`;
const common = `precision highp float;varying vec2 vUv;uniform vec2 texel;`;
const shaders = {
  splat: `${common}uniform sampler2D source;uniform vec2 point;uniform vec3 color;uniform float radius,aspect;void main(){vec2 p=vUv-point;p.x*=aspect;vec3 s=texture2D(source,vUv).xyz;gl_FragColor=vec4(s+exp(-dot(p,p)/radius)*color,1.);}`,
  advect: `${common}uniform sampler2D velocity,source;uniform float dt,dissipation;void main(){vec2 v=texture2D(velocity,vUv).xy;vec2 uv=vUv-dt*v*texel;gl_FragColor=vec4(texture2D(source,clamp(uv,vec2(0.001),vec2(.999))).xyz*dissipation,1.);}`,
  curl: `${common}uniform sampler2D velocity;void main(){float L=texture2D(velocity,vUv-vec2(texel.x,0)).y;float R=texture2D(velocity,vUv+vec2(texel.x,0)).y;float B=texture2D(velocity,vUv-vec2(0,texel.y)).x;float T=texture2D(velocity,vUv+vec2(0,texel.y)).x;gl_FragColor=vec4(.5*(R-L-T+B),0.,0.,1.);}`,
  vorticity: `${common}uniform sampler2D velocity,curl;uniform float dt,strength;void main(){float L=texture2D(curl,vUv-vec2(texel.x,0)).x;float R=texture2D(curl,vUv+vec2(texel.x,0)).x;float B=texture2D(curl,vUv-vec2(0,texel.y)).x;float T=texture2D(curl,vUv+vec2(0,texel.y)).x;float C=texture2D(curl,vUv).x;vec2 force=.5*vec2(abs(T)-abs(B),abs(R)-abs(L));force/=length(force)+.0001;force*=strength*C;force.y*=-1.;gl_FragColor=vec4(texture2D(velocity,vUv).xy+force*dt,0.,1.);}`,
  divergence: `${common}uniform sampler2D velocity;void main(){vec2 v=texture2D(velocity,vUv).xy;float L=texture2D(velocity,vUv-vec2(texel.x,0)).x;float R=texture2D(velocity,vUv+vec2(texel.x,0)).x;float B=texture2D(velocity,vUv-vec2(0,texel.y)).y;float T=texture2D(velocity,vUv+vec2(0,texel.y)).y;if(vUv.x<texel.x)L=-v.x;if(vUv.x>1.-texel.x)R=-v.x;if(vUv.y<texel.y)B=-v.y;if(vUv.y>1.-texel.y)T=-v.y;gl_FragColor=vec4(.5*(R-L+T-B),0.,0.,1.);}`,
  pressure: `${common}uniform sampler2D pressure,divergence;void main(){float L=texture2D(pressure,vUv-vec2(texel.x,0)).x;float R=texture2D(pressure,vUv+vec2(texel.x,0)).x;float B=texture2D(pressure,vUv-vec2(0,texel.y)).x;float T=texture2D(pressure,vUv+vec2(0,texel.y)).x;float d=texture2D(divergence,vUv).x;gl_FragColor=vec4((L+R+B+T-d)*.25,0.,0.,1.);}`,
  gradient: `${common}uniform sampler2D pressure,velocity;void main(){float L=texture2D(pressure,vUv-vec2(texel.x,0)).x;float R=texture2D(pressure,vUv+vec2(texel.x,0)).x;float B=texture2D(pressure,vUv-vec2(0,texel.y)).x;float T=texture2D(pressure,vUv+vec2(0,texel.y)).x;gl_FragColor=vec4(texture2D(velocity,vUv).xy-.5*vec2(R-L,T-B),0.,1.);}`,
  composite: `${common}uniform sampler2D dye,photo,paper;uniform float aspect,imageAspect,still,time;vec2 cover(vec2 uv){vec2 r=vec2(min(aspect/imageAspect,1.),min(imageAspect/aspect,1.));return (uv-.5)*r+.5;}float hash(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);}void main(){vec2 uv=cover(vUv);vec3 image=texture2D(photo,uv).rgb;float gray=dot(image,vec3(.299,.587,.114));image=mix(vec3(gray),image,.12);vec3 base=texture2D(paper,vUv).rgb;float d=texture2D(dye,vUv).r;float mask=max(smoothstep(.08,.38,d),smoothstep(.45,.96,vUv.x)*.3);mask=max(mask,still*.88);float edge=smoothstep(.03,.11,d)-smoothstep(.11,.22,d);vec3 exposed=image*vec3(.83,.79,.69);vec3 color=mix(base,exposed,mask*.94);color+=vec3(.14,.065,.025)*edge*.3;float shadow=mix(.28,1.,smoothstep(0.,.75,vUv.x));color*=shadow;float grain=(hash(gl_FragCoord.xy+floor(time*12.))-.5)*.035;color+=grain;gl_FragColor=vec4(color,1.);}`
};

export class FluidReveal {
  constructor(container, { image, reduced = false, onReady = () => {} } = {}) {
    this.container = container; this.reduced = reduced; this.disposed = false; this.visible = true;
    this.targets = []; this.materials = []; this.frames = 0; this.last = 0; this.time = 0; this.splats = [];
    this.mobile = matchMedia('(max-width: 700px)').matches;
    this.resolution = this.mobile ? 128 : 256; this.dyeResolution = this.mobile ? 256 : 512;
    this.canvas = document.createElement('canvas'); this.canvas.className = 'fluid-canvas'; this.canvas.setAttribute('aria-hidden','true'); container.prepend(this.canvas);
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, alpha: false, antialias: false, powerPreference: 'high-performance' });
    if (!this.renderer.extensions.has('EXT_color_buffer_float')) { this.renderer.dispose(); this.canvas.remove(); throw new Error('Floating-point framebuffer support unavailable'); }
    this.renderer.setPixelRatio(Math.min(devicePixelRatio, this.mobile ? 1.25 : 1.6));
    this.renderer.setClearColor(0x0b0b0a); this.scene = new THREE.Scene(); this.camera = new THREE.OrthographicCamera(-1,1,1,-1,0,1);
    this.geometry = new THREE.PlaneGeometry(2,2); this.quad = new THREE.Mesh(this.geometry); this.scene.add(this.quad);
    this.texel = new THREE.Vector2(1/this.resolution,1/this.resolution);
    this.velocity = this.double(this.resolution); this.pressure = this.double(this.resolution); this.dye = this.double(this.dyeResolution);
    this.curl = this.target(this.resolution); this.divergence = this.target(this.resolution);
    this.passes = {};
    const uniformSets = {
      splat: {source:null,point:new THREE.Vector2(),color:new THREE.Vector3(),radius:.0015,aspect:1},
      advect: {velocity:null,source:null,dt:.016,dissipation:.98}, curl:{velocity:null},
      vorticity:{velocity:null,curl:null,dt:.016,strength:12}, divergence:{velocity:null},
      pressure:{pressure:null,divergence:null}, gradient:{pressure:null,velocity:null}
    };
    Object.entries(uniformSets).forEach(([name, uniforms]) => this.passes[name] = this.material(shaders[name], uniforms));
    this.paper = this.makePaper();
    this.photo = new THREE.TextureLoader().load(image, tex => {this.composite.uniforms.imageAspect.value=tex.image.width/tex.image.height;this.loaded=true;this.render();onReady();}, undefined, () => {this.failed=true;this.container.classList.add('fluid-fallback');onReady();});
    this.composite = this.material(shaders.composite, {dye:this.dye.read.texture,photo:this.photo,paper:this.paper,aspect:1,imageAspect:1.5,still:reduced?1:0,time:0});
    this.previous = null;
    this.pointer = e => { const rect = container.getBoundingClientRect(); const x=(e.clientX-rect.left)/rect.width,y=1-(e.clientY-rect.top)/rect.height;
      if(this.previous&&!this.reduced)this.splats.push({x,y,dx:(x-this.previous.x)*850,dy:(y-this.previous.y)*850,radius:.0016,ink:.7});
      this.previous={x,y}; if(this.splats.length>6)this.splats.shift(); };
    this.leave=()=>this.previous=null;
    container.addEventListener('pointermove',this.pointer,{passive:true});container.addEventListener('pointerleave',this.leave);
    this.ro=new ResizeObserver(()=>this.resize());this.ro.observe(container);
    this.io=new IntersectionObserver(entries=>{this.visible=entries[0].isIntersecting;this.wake();});this.io.observe(container);
    this.visibility=()=>this.wake();document.addEventListener('visibilitychange',this.visibility);
    this.tick=this.tick.bind(this);this.resize();this.wake();
  }
  makePaper(){ const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1000;const ctx=canvas.getContext('2d');ctx.fillStyle='#121210';ctx.fillRect(0,0,1600,1000);ctx.strokeStyle='#33342c';ctx.lineWidth=1;for(let x=0;x<1600;x+=80){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,1000);ctx.stroke()}for(let y=0;y<1000;y+=80){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1600,y);ctx.stroke()}ctx.strokeStyle='#676650';ctx.lineWidth=2;ctx.beginPath();ctx.arc(1120,500,340,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(1120,500,260,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#777363';ctx.font='13px monospace';ctx.fillText('РЕДАКЦИОННЫЙ СЛОЙ / НЕ АРХИВНЫЙ ДОКУМЕНТ',950,950);const texture=new THREE.CanvasTexture(canvas);this.paperCanvas=canvas;return texture; }
  material(fragmentShader, values){const uniforms={texel:{value:this.texel}};Object.entries(values).forEach(([k,value])=>uniforms[k]={value});const mat=new THREE.ShaderMaterial({vertexShader:vertex,fragmentShader,uniforms,depthTest:false,depthWrite:false});this.materials.push(mat);return mat;}
  target(size){const t=new THREE.WebGLRenderTarget(size,size,{format:THREE.RGBAFormat,type:THREE.HalfFloatType,minFilter:THREE.LinearFilter,magFilter:THREE.LinearFilter,depthBuffer:false,stencilBuffer:false});this.targets.push(t);this.renderer.setRenderTarget(t);this.renderer.clear();this.renderer.setRenderTarget(null);return t;}
  double(size){return {read:this.target(size),write:this.target(size),swap(){[this.read,this.write]=[this.write,this.read]}};}
  pass(name, target, values={}){const m=typeof name==='string'?this.passes[name]:name;Object.entries(values).forEach(([k,v])=>m.uniforms[k].value=v);this.quad.material=m;this.renderer.setRenderTarget(target);this.renderer.render(this.scene,this.camera);}
  inject({x,y,dx,dy,radius,ink}){const common={point:new THREE.Vector2(x,y),aspect:this.width/this.height,radius};this.pass('splat',this.velocity.write,{...common,source:this.velocity.read.texture,color:new THREE.Vector3(dx,dy,0)});this.velocity.swap();this.pass('splat',this.dye.write,{...common,source:this.dye.read.texture,color:new THREE.Vector3(ink,ink,ink)});this.dye.swap();}
  step(dt){
    if(this.time<4.4&&this.frames%3===0){const t=this.time;this.inject({x:.69+Math.sin(t*1.5)*.18,y:.51+Math.cos(t*2.3)*.27,dx:Math.cos(t*1.5)*60,dy:Math.sin(t*2.3)*60,radius:.015,ink:.7});}
    this.splats.splice(0).forEach(s=>this.inject(s));
    this.pass('curl',this.curl,{velocity:this.velocity.read.texture});
    this.pass('vorticity',this.velocity.write,{velocity:this.velocity.read.texture,curl:this.curl.texture,dt});this.velocity.swap();
    this.pass('advect',this.velocity.write,{velocity:this.velocity.read.texture,source:this.velocity.read.texture,dt,dissipation:.975});this.velocity.swap();
    this.pass('advect',this.dye.write,{velocity:this.velocity.read.texture,source:this.dye.read.texture,dt,dissipation:.998});this.dye.swap();
    this.pass('divergence',this.divergence,{velocity:this.velocity.read.texture});
    this.renderer.setRenderTarget(this.pressure.read);this.renderer.clear();
    for(let i=0;i<(this.mobile?12:20);i++) {this.pass('pressure',this.pressure.write,{pressure:this.pressure.read.texture,divergence:this.divergence.texture});this.pressure.swap();}
    this.pass('gradient',this.velocity.write,{velocity:this.velocity.read.texture,pressure:this.pressure.read.texture});this.velocity.swap();
    this.render();
  }
  render(){if(this.disposed||!this.composite)return;this.composite.uniforms.dye.value=this.dye.read.texture;this.composite.uniforms.time.value=this.time;this.composite.uniforms.still.value=this.reduced?1:0;this.pass(this.composite,null);}
  resize(){if(this.disposed)return;this.width=Math.max(1,this.container.clientWidth);this.height=Math.max(1,this.container.clientHeight);this.renderer.setSize(this.width,this.height,false);if(this.composite)this.composite.uniforms.aspect.value=this.width/this.height;this.render();}
  tick(now){this.frame=0;if(this.disposed||!this.visible||document.hidden||this.reduced)return;const dt=Math.min((now-(this.last||now-16))/1000,.025);this.last=now;this.time+=dt;this.frames++;this.step(dt);this.frame=requestAnimationFrame(this.tick);}
  wake(){if(this.frame)cancelAnimationFrame(this.frame);this.frame=0;if(this.disposed)return;this.last=0;if(this.reduced){this.render();return}if(this.visible&&!document.hidden)this.frame=requestAnimationFrame(this.tick);}
  setReduced(v){this.reduced=v;this.wake();}
  destroy(){if(this.disposed)return;this.disposed=true;cancelAnimationFrame(this.frame);this.container.removeEventListener('pointermove',this.pointer);this.container.removeEventListener('pointerleave',this.leave);document.removeEventListener('visibilitychange',this.visibility);this.ro.disconnect();this.io.disconnect();this.targets.forEach(t=>t.dispose());this.materials.forEach(m=>m.dispose());this.geometry.dispose();this.photo.dispose();this.paper.dispose();this.renderer.dispose();this.canvas.remove();}
  stats(){return {frames:this.frames,resolution:this.resolution,dyeResolution:this.dyeResolution,pressureIterations:this.mobile?12:20,renderTargets:this.targets.length,reduced:this.reduced,visible:this.visible,textureLoaded:!!this.loaded,disposed:this.disposed};}
}
