import media from './media.json';
import { documents } from './content';

gsap.registerPlugin(ScrollTrigger, SplitText, Flip, InertiaPlugin);
document.documentElement.classList.remove('no-js');
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const mq=matchMedia('(prefers-reduced-motion: reduce)');
let reduced=mq.matches, page=null, menuOpen=false, menuFocus=null, navigationCount=0, gallery=null;
try{const stored=sessionStorage.getItem('chronicle-motion');if(stored!==null)reduced=stored==='off';}catch(e){}
const lenis=new Lenis({lerp:.085,smoothWheel:true,anchors:true,prevent:node=>node.hasAttribute('data-lenis-prevent')});
lenis.on('scroll',ScrollTrigger.update);
const cursor=$('.cursor-label'), cursorState={x:-200,y:-200,tx:-200,ty:-200};
let debugFrame=0;
function tick(time){lenis.raf(time*1000);if(++debugFrame%45===0&&window.__CHRONICLE__)document.documentElement.dataset.runtime=JSON.stringify(window.__CHRONICLE__.stats());cursorState.x+=(cursorState.tx-cursorState.x)*.09;cursorState.y+=(cursorState.ty-cursorState.y)*.09;gsap.set(cursor,{x:cursorState.x-42,y:cursorState.y-42});}
gsap.ticker.add(tick);gsap.ticker.lagSmoothing(0);
const cursorMove=e=>{cursorState.tx=e.clientX;cursorState.ty=e.clientY;};addEventListener('pointermove',cursorMove,{passive:true});
function updateMotionButton(){document.body.classList.toggle('no-motion',reduced);const b=$('.motion-toggle');b.setAttribute('aria-pressed',String(reduced));b.setAttribute('aria-label',reduced?'Включить анимацию':'Отключить анимацию');}
function setMotion(value){reduced=value;try{sessionStorage.setItem('chronicle-motion',reduced?'off':'on')}catch(e){}updateMotionButton();if(page){const view=page.view;page.destroy();page=new Page(view,{intro:false});}if(reduced)lenis.options.smoothWheel=false;else lenis.options.smoothWheel=true;}
$('.motion-toggle').addEventListener('click',()=>setMotion(!reduced));mq.addEventListener('change',e=>setMotion(e.matches));updateMotionButton();

const menu=$('.menu-overlay');
function closeMenu(immediate=false){if(!menuOpen)return;menuOpen=false;document.documentElement.classList.remove('menu-open');$('.menu-toggle').setAttribute('aria-expanded','false');lenis.start();const done=()=>{menu.setAttribute('aria-hidden','true');menu.inert=true;menuFocus?.focus({preventScroll:true});};if(reduced||immediate)done();else gsap.to(menu,{opacity:0,duration:.3,onComplete:()=>{done();gsap.set(menu,{clearProps:'opacity'})}});}
function openMenu(){menuOpen=true;document.documentElement.classList.add('menu-open');menuFocus=document.activeElement;lenis.stop();menu.inert=false;menu.setAttribute('aria-hidden','false');$('.menu-toggle').setAttribute('aria-expanded','true');if(!reduced){gsap.fromTo(menu,{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0 0 0% 0)',duration:.65,ease:'power4.inOut'});gsap.fromTo($$('.menu-links a'),{y:45,opacity:0},{y:0,opacity:1,duration:.65,stagger:.06,delay:.2,ease:'power3.out'});}$('.menu-close').focus();}
$('.menu-toggle').addEventListener('click',()=>menuOpen?closeMenu():openMenu());$('.menu-close').addEventListener('click',()=>closeMenu());$$('.menu-links a').forEach(a=>a.addEventListener('click',()=>closeMenu(true)));
menu.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeMenu();}if(e.key==='Tab'){const list=$$('button,a',menu),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});

function openPhoto(button,item){if(gallery)return;const dialog=$('.photo-dialog'),img=$('img',button),state=Flip.getState(img);const marker=document.createElement('div');marker.style.width=img.offsetWidth+'px';marker.style.height=img.offsetHeight+'px';marker.className='photo-placeholder';img.before(marker);gallery={img,button,marker,item};$('.viewer-caption span',dialog).textContent=item.caption+' '+item.credit;$('.viewer-caption a',dialog).href=item.url;lenis.stop();document.documentElement.classList.add('gallery-open');dialog.showModal();$('.viewer-stage',dialog).append(img);if(!reduced)Flip.from(state,{duration:.8,ease:'power4.inOut',scale:true,absolute:true});$('.viewer-close').focus();}
function closePhoto(immediate=false){if(!gallery)return;const {img,button,marker}=gallery;Flip.killFlipsOf(img);const state=Flip.getState(img),dialog=$('.photo-dialog');marker.replaceWith(img);dialog.close();document.documentElement.classList.remove('gallery-open');gallery=null;if(!reduced&&!immediate)Flip.from(state,{duration:.7,ease:'power4.inOut',scale:true,absolute:true,clearProps:'all'});else gsap.set(img,{clearProps:'all'});lenis.start();button.focus({preventScroll:true});}
$('.viewer-close').addEventListener('click',()=>closePhoto());$('.photo-dialog').addEventListener('cancel',e=>{e.preventDefault();closePhoto()});

class Page {
  constructor(view,{intro=false}={}){this.view=view;this.cleanups=[];this.splits=[];this.fluid=null;this.destroyed=false;this.id=view.dataset.taxiView;this.mount(intro);}
  listen(el,type,fn,opts){el.addEventListener(type,fn,opts);this.cleanups.push(()=>el.removeEventListener(type,fn,opts));}
  mount(intro){
    this.renderDocuments();
    this.context=gsap.context(()=>{
      if(!reduced){
        $$('[data-lines]',this.view).forEach(el=>{const split=SplitText.create(el,{type:'lines',mask:'lines',autoSplit:true,onSplit:self=>gsap.from(self.lines,{yPercent:110,duration:1.05,stagger:.085,ease:'power4.out',scrollTrigger:{trigger:el,start:'top 88%',once:true}})});this.splits.push(split);});
        const heroEls=$$('[data-hero-split]',this.view);if(heroEls.length){heroEls.forEach(el=>{const split=SplitText.create(el,{type:'chars',smartWrap:true});this.splits.push(split);gsap.from(split.chars,{yPercent:115,rotation:5,duration:1.3,stagger:.025,ease:'power4.out',delay:intro?1:.15});});gsap.from('.hero-intro,.hero-topline,.hero-bottom',{y:20,opacity:0,duration:1,stagger:.12,delay:intro?1.2:.4});gsap.to('.hero-crosshair',{rotation:180,duration:30,repeat:-1,ease:'none'});}
        $$('[data-archive-title]',this.view).forEach(el=>{const split=SplitText.create(el,{type:'chars'});this.splits.push(split);gsap.from(split.chars,{yPercent:100,opacity:0,duration:1,stagger:.045,ease:'power4.out',delay:intro?.8:.1});});
        const mm=gsap.matchMedia();mm.add('(min-width: 701px)',()=>{
          const stage=$('.cinema-stage',this.view);if(stage){const tl=gsap.timeline({scrollTrigger:{trigger:stage,start:'top top',end:'+=110%',pin:true,scrub:1,invalidateOnRefresh:true}});tl.fromTo($('.cinema-image',stage),{clipPath:'inset(14% 18% 14% 18%)'},{clipPath:'inset(0% 0% 0% 0%)',duration:1},0).fromTo($('.cinema-image img',stage),{scale:1.35},{scale:1,duration:1.5},0).fromTo($('.cinema-title',stage),{y:95},{y:-55,duration:1.5},0).fromTo($('.cinema-copy',stage),{opacity:0,y:30},{opacity:1,y:0,duration:.4},.7);}
          const timeline=$('.chronology',this.view),track=$('.chronology-track',this.view);if(track){const distance=()=>Math.max(0,track.scrollWidth-$('.chronology-viewport',this.view).clientWidth);gsap.to(track,{x:()=>-distance(),ease:'none',scrollTrigger:{trigger:timeline,start:'top top',end:()=>'+='+(distance()+500),pin:true,scrub:1,invalidateOnRefresh:true}});}
        });
        const running=$('.running-inner',this.view);if(running)gsap.to(running,{xPercent:-30,ease:'none',scrollTrigger:{trigger:running.parentElement,start:'top bottom',end:'bottom top',scrub:2}});
        const photo=$('.turning-photo img',this.view);if(photo)gsap.to(photo,{yPercent:-12,ease:'none',scrollTrigger:{trigger:photo.parentElement,start:'top bottom',end:'bottom top',scrub:1.4}});
        const title=$('[data-scrub-title]',this.view);if(title)gsap.fromTo(title,{xPercent:8},{xPercent:-3,ease:'none',scrollTrigger:{trigger:title,start:'top bottom',end:'bottom top',scrub:1.6}});
        const endPhoto=$('.end-photo img',this.view);if(endPhoto)gsap.to(endPhoto,{yPercent:-15,ease:'none',scrollTrigger:{trigger:$('.end-scene',this.view),start:'top bottom',end:'bottom top',scrub:1}});
        const date=$('[data-victory-date]',this.view);if(date){const split=SplitText.create(date,{type:'chars'});this.splits.push(split);gsap.from(split.chars,{yPercent:90,rotation:6,opacity:0,ease:'power4.out',duration:1.4,stagger:.08,scrollTrigger:{trigger:date,start:'top 90%',once:true}});}
        const days=$('[data-char-fall]',this.view);if(days){const split=SplitText.create(days,{type:'chars'});this.splits.push(split);gsap.from(split.chars,{y:100,rotation:10,opacity:0,duration:1.2,stagger:.12,ease:'power4.out',scrollTrigger:{trigger:days,start:'top 85%',once:true}});}
        $$('.archive-card',this.view).forEach(el=>gsap.from(el,{y:75,opacity:0,duration:1,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 92%',once:true}}));
      }
    },this.view);
    const hero=$('[data-fluid]',this.view);if(hero){try{this.fluid=new FluidReveal(hero,{image:new URL(hero.dataset.fluid.replace(/^\//,''),document.baseURI).href,reduced,onReady:()=>hero.dataset.textureReady='true'});}catch(e){hero.classList.add('fluid-fallback');$('.runtime-status').textContent='На этом устройстве WebGL-слой недоступен. Показана архивная фотография без симуляции.';$('.runtime-status').classList.add('visible');console.warn(e);}}
    this.setupGlitch();this.setupHover();this.setupStamp();this.setupPhotos();this.setupVideo();this.setupSectionIndex();
    $$('img',this.view).forEach(img=>{if(!img.complete)this.listen(img,'load',()=>ScrollTrigger.refresh(),{once:true});});
    $$('details',this.view).forEach(d=>this.listen(d,'toggle',()=>{lenis.resize();ScrollTrigger.refresh();}));
    requestAnimationFrame(()=>{if(!this.destroyed){lenis.resize();ScrollTrigger.refresh();}});
  }
  setupGlitch(){const el=$('[data-scroll-glitch]',this.view);if(!el||reduced)return;const original=el.textContent;el.setAttribute('aria-label',original);const visual=document.createElement('span');visual.setAttribute('aria-hidden','true');visual.textContent=original;el.replaceChildren(visual);let energy=0,frame=0,count=0;const letters='АБВГДЕЖЗИКЛМНОПРСТУФХ0123456789';const render=()=>{energy*=.85;if(++count%3===0)visual.textContent=[...original].map(c=>c===' '?c:Math.random()<energy?letters[Math.floor(Math.random()*letters.length)]:c).join('');if(energy>.015)frame=requestAnimationFrame(render);else{visual.textContent=original;frame=0;}};const st=ScrollTrigger.create({trigger:el,start:'top bottom',end:'bottom top',onUpdate:self=>{energy=Math.min(.5,Math.abs(self.getVelocity())/6000);if(!frame)frame=requestAnimationFrame(render);}});this.cleanups.push(()=>{st.kill();cancelAnimationFrame(frame);el.textContent=original;el.removeAttribute('aria-label');});}
  setupHover(){
    $$('.wordmark svg g path,.hero-title .star path',document).forEach(el=>{const parent=el.closest('a,svg');const enter=()=>{if(!reduced)gsap.fromTo(el,{scale:1},{scale:.15,duration:.35,transformOrigin:'50% 50%',yoyo:true,repeat:1,ease:'power3.inOut'})};this.listen(parent,'pointerenter',enter);});
    $$('.photo-open',this.view).forEach(el=>{this.listen(el,'pointerenter',()=>{if(!reduced)gsap.to(cursor,{opacity:1,duration:.25})});this.listen(el,'pointerleave',()=>gsap.to(cursor,{opacity:0,duration:.2}));});
    // Same distance-based magnetic response as the reference's [hoverme] text.
    const cta=$('.archive-cta',this.view);if(cta&&!reduced&&matchMedia('(pointer:fine)').matches){const arrow=$('.arrow',cta);this.listen(cta,'pointermove',e=>{const r=arrow.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2);if(Math.hypot(dx,dy)<230)gsap.to(arrow,{x:dx*.18,y:dy*.18,rotation:8,duration:.65,ease:'power3.out'});});this.listen(cta,'pointerleave',()=>gsap.to(arrow,{x:0,y:0,rotation:0,duration:1.2,ease:'elastic.out(1,.4)'}));this.cleanups.push(()=>gsap.killTweensOf(arrow));}
  }
  setupStamp(){const stamp=$('[data-inertia]',this.view);if(!stamp)return;InertiaPlugin.track(stamp,'x,y,rotation');let drag=null;const down=e=>{if(reduced)return;gsap.killTweensOf(stamp);drag={id:e.pointerId,x:e.clientX,y:e.clientY,ox:gsap.getProperty(stamp,'x'),oy:gsap.getProperty(stamp,'y')};stamp.setPointerCapture(e.pointerId);};const move=e=>{if(!drag||drag.id!==e.pointerId)return;const x=Math.max(-80,Math.min(80,drag.ox+e.clientX-drag.x)),y=Math.max(-60,Math.min(60,drag.oy+e.clientY-drag.y));gsap.set(stamp,{x,y,rotation:-9+x*.1});};const up=()=>{if(!drag)return;drag=null;gsap.to(stamp,{inertia:{x:{velocity:'auto',end:0},y:{velocity:'auto',end:0},rotation:{velocity:'auto',end:-9}},ease:'power3.out',onComplete:()=>gsap.set(stamp,{x:0,y:0,rotation:-9})});};this.listen(stamp,'pointerdown',down);this.listen(stamp,'pointermove',move);this.listen(stamp,'pointerup',up);this.listen(stamp,'pointercancel',up);this.listen(stamp,'keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||reduced)return;e.preventDefault();const axis=e.key.includes('Left')||e.key.includes('Right')?'x':'y',value=e.key.includes('Left')||e.key.includes('Up')?-25:25;gsap.fromTo(stamp,{[axis]:value},{[axis]:0,duration:1.2,ease:'elastic.out(1,.35)'});});this.cleanups.push(()=>{InertiaPlugin.untrack(stamp);gsap.killTweensOf(stamp);gsap.set(stamp,{clearProps:'transform'});});}
  setupPhotos(){const items=[...media,...documents.map((d,i)=>({id:'custom-'+i,...d,url:d.source||'#'}))];$$('[data-photo]',this.view).forEach(button=>this.listen(button,'click',()=>{const item=items.find(i=>i.id===button.dataset.photo);if(item)openPhoto(button,item);}));}
  renderDocuments(){const container=$('#user-materials',this.view);if(!container)return;documents.forEach((item,i)=>{const figure=document.createElement('figure');figure.className='archive-card';let node;if(item.type==='video'){node=document.createElement('video');node.src=item.src;node.controls=true;node.playsInline=true;node.preload='metadata';if(item.poster)node.poster=item.poster;node.style.cssText='width:100%;max-height:75vh;background:#151611';node.setAttribute('aria-label',item.title);}else{node=document.createElement('button');node.className='photo-open';node.dataset.photo='custom-'+i;node.setAttribute('aria-label','Рассмотреть: '+item.title);const img=document.createElement('img');img.src=item.src;img.alt=item.caption||item.title;node.append(img);}const caption=document.createElement('figcaption'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=item.title;p.textContent=[item.caption,item.credit].filter(Boolean).join(' · ');caption.append(h,p);if(item.source){try{const u=new URL(item.source);if(['https:','http:'].includes(u.protocol)){const a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Источник ↗';caption.append(a)}}catch(e){}}figure.append(node,caption);container.append(figure);});}
  setupVideo(){const videos=$$('video',this.view);if(!videos.length)return;const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)e.target.pause()}));videos.forEach(v=>io.observe(v));this.cleanups.push(()=>{io.disconnect();videos.forEach(v=>{v.pause();gsap.killTweensOf(v)})});}
  setupSectionIndex(){const links=$$('.route-indicator a',this.view);if(!links.length)return;const sections=links.map(a=>$(a.getAttribute('href'),this.view)).filter(Boolean),io=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}});},{rootMargin:'-20% 0px -45% 0px',threshold:0});sections.forEach(s=>io.observe(s));this.cleanups.push(()=>io.disconnect());}
  destroy(){if(this.destroyed)return;this.destroyed=true;closePhoto(true);this.context?.revert();this.splits.forEach(s=>s.revert());this.cleanups.forEach(f=>f());this.fluid?.destroy();const custom=$('#user-materials',this.view);if(custom)custom.replaceChildren();gsap.set(cursor,{opacity:0});}
}

const curtain=$('.route-curtain');
class CurtainTransition extends Transition {
  onLeave({from,done,trigger}){closeMenu(true);closePhoto(true);lenis.stop();const label=trigger?.dataset?.routeLabel||'1941—1945';$('span',curtain).textContent=label;const finish=()=>{page?.destroy();done();};if(reduced){gsap.set(curtain,{yPercent:0});finish();}else gsap.fromTo(curtain,{yPercent:100},{yPercent:0,duration:.65,ease:'power4.inOut',onComplete:finish});}
  onEnter({to,done}){window.scrollTo(0,0);lenis.scrollTo(0,{immediate:true,force:true});page=new Page(to);navigationCount++;if(window.__CHRONICLE__)document.documentElement.dataset.runtime=JSON.stringify(window.__CHRONICLE__.stats());const finish=()=>{gsap.set(curtain,{yPercent:100});lenis.start();const hash=location.hash;if(hash){const el=$(hash,to);if(el)lenis.scrollTo(el,{immediate:reduced,offset:-25});}done();};if(reduced)finish();else gsap.to(curtain,{yPercent:-100,duration:.8,ease:'power4.inOut',delay:.1,onComplete:finish});}
}
let taxi;
try{taxi=new Core({transitions:{default:CurtainTransition},renderers:{default:Renderer,home:Renderer,archive:Renderer},reloadJsFilter:false,reloadCssFilter:false,removeOldContent:true,links:'a:not([target]):not([href^="#"]):not([data-taxi-ignore])'});}catch(e){console.warn('Taxi unavailable; native links retained.',e);}
function progress(){const max=document.documentElement.scrollHeight-innerHeight;gsap.set('.read-progress',{scaleX:max>0?Math.min(1,scrollY/max):0});}addEventListener('scroll',progress,{passive:true});
async function start(){lenis.stop();try{await document.fonts.ready}catch(e){}page=new Page($('[data-taxi-view]'),{intro:true});const loader=$('.loader');if(reduced){gsap.set(loader,{display:'none'});lenis.start();}else{const counter={year:1941};gsap.timeline({onComplete:()=>{gsap.set(loader,{display:'none'});lenis.start();ScrollTrigger.refresh();}}).to(counter,{year:1945,duration:.85,snap:{year:1},ease:'power1.inOut',onUpdate:()=>$('.load-number').textContent=counter.year},0).to('.load-rule',{scaleX:1,duration:.9,ease:'power2.inOut'},0).to(loader,{yPercent:-100,duration:.9,ease:'power4.inOut'},.9);}}
start().catch(e=>{console.error(e);gsap.set('.loader',{display:'none'});lenis.start();$('.runtime-status').textContent='Часть интерактивных эффектов недоступна. Содержимое остаётся доступно.';$('.runtime-status').classList.add('visible');});
window.__CHRONICLE__={stats:()=>({three:THREE.REVISION,gsap:gsap.version,lenis:Lenis.version||'1.2.3',taxi:!!taxi,page:page?.id,navigations:navigationCount,scrollTriggers:ScrollTrigger.getAll().length,splits:page?.splits.length||0,fluid:page?.fluid?.stats()||null,reduced,menuOpen,galleryOpen:!!gallery}),setReduced:setMotion};
addEventListener('pagehide',e=>{if(e.persisted)return;page?.destroy();lenis.destroy();gsap.ticker.remove(tick);removeEventListener('pointermove',cursorMove);},{once:true});
